<span class="line"><span style="color:#E1E4E8;">            order_change </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> ((today_orders </span><span style="color:#F97583;">-</span><span style="color:#E1E4E8;"> yesterday_orders) </span><span style="color:#F97583;">/</span><span style="color:#E1E4E8;"> yesterday_orders) </span><span style="color:#F97583;">*</span><span style="color:#79B8FF;"> 100</span></span>
